import numpy as np

cdef extern from "gsl/gsl_stats.h":
    cdef double gsl_stats_median_from_sorted_data(
        double *data, int stride, int n)

def compute_median(sorted_data, stride, n):
    if not isinstance(sorted_data, (list, np.ndarray)):
        raise TypeError("Input data must be a list or numpy array")
    if not all(isinstance(x, (int, float)) for x in sorted_data):
        raise ValueError("All elements must be numeric")
    if n <= 0:
        raise ValueError("Number of elements must be positive")
    if stride <= 0:
        raise ValueError("Stride must be positive")

    if isinstance(sorted_data, list):
        data = (ctypes.c_double * len(sorted_data))(*sorted_data)
    else:
        data = np.ctypeslib.as_ctypes(sorted_data)

    try:
        lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
        result = gsl.gsl_stats_median_from_sorted_data(data, stride, n)
        return float(result)
    except Exception as e:
        raise RuntimeError(f"GSL library error: {str(e)}")

# Test cases
if __name__ == "__main__":
    try:
        # Test case 1: odd number of elements
        data1 = [1.0, 2.0, 3.0]
        print(f"Test 1: {compute_median(data1, 1, 3)}")  # Expected: 2.0

        # Test case 2: even number of elements
        data2 = [1.0, 2.0, 3.0, 4.0]
        print(f"Test 2: {compute_median(data2, 1, 4)}")  # Expected: 2.5

        # Test case 3: stride > 1
