        return 1
    if ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_get_size1(dest.matrix) != ctypes.CDLL("/usr/local/gsl/lib/libgsl/libgsl.so").gsl_matrix_get_size1(src.matrix) or \n        ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_get_size2(dest.matrix) != ctypes.CDLL("/usr/local/gsl/lib/libgsl.so").gsl_matrix_get_size2(src.matrix):
