class gsl_rng:
    _lib = None
    _rng = None

    @classmethod
    def init(cls, seed):
        if cls._lib is None:
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
            cls._lib = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

        cls._lib.gsl_rng_set.argtypes = [ctypes.c_long]
        cls._lib.gsl_rng_set.restype = None

        cls._lib.gsl_rng_get.argtypes = []
        cls._lib.gsl_rng_get.restype = ctypes.c_double

        cls._rng = cls._lib.gsl_rng_alloc(ctypes.c_int(5))  # 5 is gsl_rng_mt19937
        cls._lib.gsl_rng_set(cls._rng, seed)

    @classmethod
    def generate_random_numbers(cls, count):
        if cls._rng is None:
            raise ValueError("RNG not initialized")

        result = []
        for _ in range(count):
            result.append(cls._lib.gsl_rng_get(cls._rng))
        return result


