def compute_complex_roots(coefficients):
    if not isinstance(coefficients, list) or not all(isinstance(x, float) for x in coefficients):
        raise ValueError("Coefficients must be a list of floats")

    n = len(coefficients) - 1
    workspace = GSLPolyComplexWorkspace(n)
    roots = np.empty((n, 2), dtype=np.float64)

    try:
        gsl.gsl_poly_complex_solve.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.POINTER(ctypes.c_double)]
        gsl.gsl_poly_complex_solve.restype = ctypes.c_int

        coeff_array = (ctypes.c_double * len(coefficients))(*coefficients)
        real_part = (ctypes.c_double * n)()
        imag_part = (ctypes.c_double * n)()

        result = gsl.gsl_poly_complex_solve(coeff_array, len(coefficients), real_part, imag_part)
        if result != 0:
            raise RuntimeError(f"Error solving polynomial: {result}")

