import numpy as np
import json

class GSLMatrix:
    def __init__(self, data):
        self.data = np.array(data, dtype=np.float64).flatten()
        self.size = len(data)

    def to_c_array(self):
        return ctypes.c_double * self.size(self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_double)))

class GSLPermutation:
    def __init__(self, size):
        self.size = size
        self.data = np.zeros(size, dtype=np.int32)

    def to_c_array(self):
        return ctypes.c_int32 * self.size(self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_int32)))


def lu_decomposition(matrix):
    ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
    gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")

    gsl.gsl_linalg_LU_decomp.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_int), ctypes.POINTER(ctypes.c_int)]
    gsl.gsl_linalg_LU_decomp.restype = ctypes.c_int

    mat = GSLMatrix(matrix)
    perm = GSLPermutation(len(matrix))
    signum = ctypes.c_int(0)

    mat_c = mat.to_c_array()
    perm_c = perm.to_c_array()

    status = gsl.gsl_linalg_LU_decomp(mat_c, ctypes.c_int(len(matrix)), perm_c, ctypes.byref(signum))

    if status != 0:
        raise Exception(f"LU decomposition failed with status {status}")

    lu_matrix = np.array([mat.data[i * len(matrix):(i + 1) * len(matrix)] for i in range(len(matrix))])
    perm_list = perm.data.tolist()
    signum_value = signum.value

    return lu_matrix.tolist(), perm_list, signum_value

