    gsl.gsl_linalg_LU_decomp.restype = ctypes.c_int

    mat = GSLMatrix(matrix)
    perm = GSLPermutation(mat.size)
    signum = ctypes.c_int(0)

    gsl.gsl_linalg_LU_decomp(mat.storage, mat.size, perm.perm, ctypes.byref(signum))

