        self.size = size
        self.data = np.zeros((size, size), dtype=np.float64)
        self._pointer = self.data.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    def set_data(self, data):
        self.data[:] = data

    def get_data(self):
        return self.data.copy()

    def __str__(self):
        return str(self.data)

def matrix_to_gsl(matrix):
    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise ValueError("Input matrix must be a 2D list of floats")
    rows, cols = len(matrix), len(matrix[0])
    if not all(len(row) == cols for row in matrix):
        raise ValueError("All rows in matrix must have the same length")
    if rows != cols:
        raise ValueError("Matrix must be square")
    gsl_matrix = GSLMatrix(rows)
    gsl_matrix.set_data(matrix)
    return gsl_matrix

def gsl_matrix_to_numpy(gsl_matrix):
    return gsl_matrix.get_data().copy()

def compute_matrix_exponential(matrix, mode):
    try:
        gsl_cblas = ctypes.CDLL("/usr/local/gsl/lib/libgslcblas.so", mode=ctypes.RTLD_GLOBAL)
        gsl = ctypes.CDLL("/usr/local/gsl/lib/libgsl.so")
    except OSError as e:
        print(f"Error loading GSL libraries: {e}")
        sys.exit(1)

    gsl.gsl_linalg_exponential_ss.argtypes = [ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.POINTER(ctypes.c_double), ctypes.c_int, ctypes.c_int]
    gsl.gsl_linalg_exponential_ss.restype = ctypes.c_int

    if not isinstance(matrix, list) or not all(isinstance(row, list) for row in matrix):
        raise ValueError("Input matrix must be a 2D list of floats")
    rows, cols = len(matrix), len(matrix[0])
    if not all(len(row) == cols for row in matrix):
        raise ValueError("All rows in matrix must have the same length")
    if rows != cols:
        raise ValueError("Matrix must be square")

    gsl_matrix = matrix_to_gsl(matrix)
    result = np.zeros((rows, cols), dtype=np.float64)
    result_ptr = result.ctypes.data_as(ctypes.POINTER(ctypes.c_double))

    status = gsl.gsl_linalg_exponential_ss(gsl_matrix._pointer, rows, result_ptr, mode, 0)
    if status != 0:
        raise RuntimeError(f"GSL matrix exponential computation failed with status {status}")

    return gsl_matrix_to_numpy(gsl_matrix)

