    def free(self):
        pass

    def to_numpy(self):
        return np.ctypeslib.as_array(self.data, shape=(self.rows, self.cols))


def list_to_ctypes_matrix(lst):
    rows = len(lst)
    cols = len(lst[0])
    matrix = GSLMatrix(None, rows, cols)
    for i in range(rows):
        for j in range(cols):
            matrix.data[i][j] = lst[i][j]
    return matrix


