gsl_gsl_cdf_negative_binomial_Q = gsl.declare("double gsl_cdf_negative_binomial_Q(unsigned int k, double p, double n)", (ctypes.c_uint, ctypes.c_double, ctypes.c_double), ctypes.c_double)


def negative_binomial_cdf_P(k, p, n):
    if not isinstance(k, int) or k < 0:
        raise ValueError("k must be a non-negative integer")
    if not isinstance(p, (int, float)) or p <= 0 or p >= 1:
        raise ValueError("p must be in (0, 1)")
    if not isinstance(n, (int, float)) or n <= 0:
        raise ValueError("n must be positive")
    return gsl_gsl_cdf_negative_binomial_P(k, p, n)

def negative_binomial_cdf_Q(k, p, n):
    if not isinstance(k, int) or k < 0:
        raise ValueError("k must be a non-negative integer")
    if not isinstance(p, (int, float)) or p <= 0 or p >= 1:
        raise, ValueError("p must be in (0, 1)")
    if not isinstance(n, (int, float)) or n <= 0:
        raise ValueError("n must be positive")
    return gsl_gsl_cdf_negative_binomial_Q(k, p, n)

